extends CharacterBody3D
## Hari in 3D: camera-relative walking on the XZ plane, a billboard image per state.
## Reads keys through Controls, reports to the logic only through Story's thin interface
## (player_x, set_moving) and shows Story.hari_state.

const Spec = preload("res://logic/hari_spec.gd")
const Billboard = preload("res://scenes/billboard_art.gd")
const ART_DIR := "res://assets/art/hari/"    ## <state_lower>.png, e.g. idle.png, keys.png
const ACCEL := 9.0                           ## m/s^2: ~0.25 s to full walking speed
const DECEL := 14.0                          ## m/s^2: settles in ~0.15 s
const STRIDE_M := 0.42                       ## distance per walk frame (feet don't slide)
const BOB_M := 0.035                         ## step bob height at full speed
const BREATH_HZ := 0.28                      ## idle breathing
const BREATH_AMOUNT := 0.007
const TURN_SECONDS := 0.14                   ## squash when facing flips

var _walk_frames: Array[String] = []
var _travel := 0.0
var _time := 0.0
var _turn := 0.0
var _facing_left := false

var camera: Camera3D
@onready var sprite: Billboard = $Sprite
@onready var label: Label3D = $StateLabel
@onready var collision: CollisionShape3D = $Collision

func _ready() -> void:
	var capsule := CapsuleShape3D.new()
	capsule.radius = Spec.CAPSULE_RADIUS
	capsule.height = Spec.CAPSULE_HEIGHT
	collision.shape = capsule
	collision.position.y = Spec.CAPSULE_HEIGHT / 2.0      # capsule bottom at the feet
	sprite.height_m = Spec.HEIGHT_M
	for i in range(1, 9):                                    # optional walk cycle: walk_1.png, walk_2.png, ...
		if ResourceLoader.exists(ART_DIR + "walk_%d.png" % i):
			_walk_frames.append(ART_DIR + "walk_%d.png" % i)
	add_child(preload("res://scenes/blob_shadow.gd").new())
	Story.hari_state_changed.connect(_show_state)
	_show_state(Story.hari_state)

func _physics_process(delta: float) -> void:
	var input: Vector2 = Vector2.ZERO if Story.movement_locked() else Controls.move_vector()
	var direction := Vector3.ZERO
	if camera and input != Vector2.ZERO:
		var right := camera.global_basis.x
		var forward := -camera.global_basis.z
		right.y = 0.0
		forward.y = 0.0
		direction = (right.normalized() * input.x + forward.normalized() * -input.y).limit_length(1.0)
		var screen_x := direction.dot(right.normalized())
		if absf(screen_x) > 0.1 and (screen_x < 0.0) != _facing_left:
			_facing_left = screen_x < 0.0                    # art faces right; flip when moving screen-left
			_turn = TURN_SECONDS
	var target_v := direction * Spec.WALK_SPEED
	var rate := ACCEL if target_v.length() > 0.01 else DECEL
	var hv := Vector3(velocity.x, 0.0, velocity.z).move_toward(target_v, rate * delta)
	velocity = Vector3(hv.x, 0.0, hv.z)
	move_and_slide()
	position.y = 0.0
	Story.player_x = global_position.x
	Story.set_moving(direction != Vector3.ZERO)

## Presentation-only motion: walk frames by distance, step bob, idle breathing, turn squash.
func _process(delta: float) -> void:
	_time += delta
	var speed := Vector2(velocity.x, velocity.z).length()
	var k := clampf(speed / Spec.WALK_SPEED, 0.0, 1.0)
	_travel += speed * delta
	var walking := Story.hari_state == "WALK"
	if walking and _walk_frames.size() > 1:
		var frame := int(_travel / STRIDE_M) % _walk_frames.size()
		sprite.set_art(_walk_frames[frame], "walk")
	# low on contact frames (even), high on passing frames (odd): a step, not a float
	var bob := (1.0 - cos(PI * (_travel / STRIDE_M - 0.5))) * 0.5 * BOB_M * k if walking else 0.0
	sprite.position.y = sprite.height_m / 2.0 + bob
	var breath := 1.0 + (sin(_time * TAU * BREATH_HZ) * BREATH_AMOUNT if not walking else 0.0)
	_turn = maxf(_turn - delta, 0.0)
	var squash := 1.0 - 0.55 * sin(PI * (1.0 - _turn / TURN_SECONDS)) if _turn > 0.0 else 1.0
	sprite.flip_h = _facing_left
	sprite.scale = Vector3(squash, breath, 1.0)

func _show_state(state: String) -> void:
	var key := state.to_lower()
	if key == "walk" and _walk_frames.size() > 1:
		sprite.set_art(_walk_frames[int(_travel / STRIDE_M) % _walk_frames.size()], key)
	else:
		sprite.set_art(ART_DIR + key + ".png", key)
	label.text = state
	label.visible = not sprite.has_art                       # state label only on placeholders

extends Node
## Dialogue flow, interaction latch and Hari's current state: logic only, no scene nodes.
##
## Thin interface with whatever presentation is loaded (3D now, could be 2D):
##   presentation -> Story : player_x (metres along the deck), nearby_target ("" / "manikandan" /
##                           "krishna"), set_moving(bool) every physics frame.
##   Story -> presentation : hari_state + hari_state_changed, movement_locked(), dialogue signals.
## Keys reach Story through Controls (press_interact / move_choice), never from the scene.

signal hari_state_changed(state: String)
signal dialogue_line(line: Dictionary)        ## a new line is up (choices included)
signal dialogue_choice_moved(index: int)
signal dialogue_closed(conversation_id: String)

const StoryData = preload("res://logic/story_data.gd")
const STATES := ["IDLE", "WALK", "TALK", "PHONE", "NOTES", "OVERHEAR", "STARTLED", "KEYS", "WHITEOUT", "RELIEF"]
const FLASH_SECONDS := {"NOTES": 1.5, "STARTLED": 1.2, "KEYS": 1.5}   ## brief states, queued over the base state
const INTERACTABLES := ["manikandan", "krishna"]
const INTERACT_COOLDOWN := 0.35     ## s after a dialogue closes before E can open another one
const MIN_LINE_SECONDS := 0.15      ## a line stays up at least this long, so mashing can't skip it unseen
const WHITEOUT_DELAY := 1.4         ## s from dawn_crash (headlights) to Hari's WHITEOUT image

var player_x := 0.0
var nearby_target := ""
var hari_state := "IDLE"                 ## what is shown: the front flash if any, else the base state
var _base_state := "IDLE"
var _flashes: Array = []                 ## queue of [state, seconds left]
var dialogue_active := false
var conversation_id := ""
var lines: Array = []
var line_index := 0
var choice_index := 0
var _line_shown_at := 0.0
var _closed_at := -10.0
var _whiteout_in := -1.0

func _ready() -> void:
	var ls: Node = _ls()
	ls.loop_started.connect(_on_loop_started)
	ls.clue_saved.connect(func(_id: String) -> void: flash_state("NOTES"))
	ls.keys_exchanged.connect(_on_keys_exchanged)
	ls.dawn_crash.connect(_on_dawn_crash)
	ls.safe_dawn.connect(_on_safe_dawn)

func _process(delta: float) -> void:
	if _whiteout_in >= 0.0:
		_whiteout_in -= delta
		if _whiteout_in < 0.0:
			set_hari_state("WHITEOUT")
	if not _flashes.is_empty():
		_flashes[0][1] -= delta
		if _flashes[0][1] <= 0.0:
			_flashes.pop_front()
			_refresh_state()

# --- presentation -> logic --------------------------------------------------------

func set_moving(moving: bool) -> void:
	if not movement_locked():
		set_hari_state("WALK" if moving else "IDLE")

func movement_locked() -> bool:
	return dialogue_active or flash_active() or _ls().phase != _ls().Phase.NIGHT

func can_interact() -> bool:
	return nearby_target in INTERACTABLES and not movement_locked()

func flash_active() -> bool:
	return not _flashes.is_empty()

## Show a brief state (NOTES / STARTLED / KEYS) for its FLASH_SECONDS, after any already queued.
func flash_state(state: String) -> void:
	_flashes.append([state, FLASH_SECONDS[state]])
	_refresh_state()

# --- keys (via Controls) ----------------------------------------------------------

## One fresh E/Space press. Advances an open dialogue, or opens a talk with the nearby NPC.
func press_interact() -> void:
	if dialogue_active:
		_advance()
		return
	if not can_interact() or _now() - _closed_at < INTERACT_COOLDOWN:
		return
	match nearby_target:
		"manikandan":
			var topic: String = _ls().talk_to_manikandan()
			if topic != "":
				start_conversation(topic)
		"krishna":
			start_conversation("krishna_ambient_repeat" if _ls().loop_index >= 2 else "krishna_ambient")

func move_choice(step: int) -> void:
	var choices := current_choices()
	if choices.is_empty():
		return
	choice_index = posmod(choice_index + step, choices.size())
	dialogue_choice_moved.emit(choice_index)

# --- dialogue ---------------------------------------------------------------------

func start_conversation(id: String) -> void:
	lines = StoryData.conversation(id)
	if lines.is_empty():
		return
	conversation_id = id
	line_index = 0
	dialogue_active = true
	_ls().talking = true
	_show_line()

func current_line() -> Dictionary:
	return lines[line_index] if dialogue_active and line_index < lines.size() else {}

func current_choices() -> Array:
	return current_line().get("choices", [])

func choice_labels() -> Array:
	return current_choices().map(func(c: Dictionary) -> String: return c.get("label", ""))

## Sets the base state (held states); a running flash still shows on top until it ends.
func set_hari_state(state: String) -> void:
	if state in STATES:
		_base_state = state
		_refresh_state()

func _refresh_state() -> void:
	var shown: String = _flashes[0][0] if not _flashes.is_empty() else _base_state
	if shown != hari_state:
		hari_state = shown
		hari_state_changed.emit(shown)

func _advance() -> void:
	if _now() - _line_shown_at < MIN_LINE_SECONDS:
		return
	var choices := current_choices()
	if not choices.is_empty():
		var action: String = choices[choice_index].get("action", "")
		if action == "ask_selvam" and _ls().ask_selvam_available():
			start_conversation("mani_ask_selvam")
		else:
			start_conversation("mani_never_mind")
		return
	line_index += 1
	if line_index >= lines.size():
		_close(true)
	else:
		_show_line()

func _show_line() -> void:
	choice_index = 0
	_line_shown_at = _now()
	var line := current_line()
	set_hari_state(line.get("hari_state", "TALK"))
	dialogue_line.emit(line)

func _close(normal_end: bool) -> void:
	if not dialogue_active:
		return
	dialogue_active = false
	_ls().talking = false
	lines = []
	_closed_at = _now()
	if normal_end and _ls().phase == _ls().Phase.NIGHT:
		# Outcomes land when the conversation has been heard to the end (flashes queue first,
		# so IDLE only shows once they finish).
		if conversation_id == "mani_overhear":
			_ls().finish_overhearing()           # -> clue_saved -> NOTES
		elif conversation_id == "mani_ask_selvam":
			_ls().ask_about_selvam()             # -> keys_exchanged -> KEYS, then clue_saved -> NOTES
		set_hari_state("IDLE")
	dialogue_closed.emit(conversation_id)

# --- LoopState events -------------------------------------------------------------

func _on_loop_started(index: int) -> void:
	_whiteout_in = -1.0
	_flashes.clear()
	_close(false)
	if index >= 2:
		flash_state("STARTLED")                  # the wake-up: at least ~1.2 s before PHONE shows
	set_hari_state("IDLE")
	start_conversation("amma_call_repeat" if index >= 2 else "amma_call_first")

func _on_keys_exchanged(_from: String, to: String) -> void:
	if to == "manikandan":
		flash_state("KEYS")

func _on_dawn_crash() -> void:
	_flashes.clear()
	_close(false)
	_refresh_state()
	_whiteout_in = WHITEOUT_DELAY

func _on_safe_dawn() -> void:
	_flashes.clear()
	_close(false)
	set_hari_state("RELIEF")

func _ls() -> Node:
	return get_node("/root/LoopState")

func _now() -> float:
	return Time.get_ticks_msec() / 1000.0

extends RefCounted
## Hari's size, collision and movement, in one place (metres). The character sheet references these.

const HEIGHT_M := 1.75              ## sprite image height maps to this (pixel_size = HEIGHT_M / texture height)
const CAPSULE_RADIUS := 0.28
const CAPSULE_HEIGHT := 1.70        ## total capsule height, bottom at the feet (y = 0)
const WALK_SPEED := 2.2             ## m/s on the XZ plane, camera-relative, no jumping
const INTERACT_RANGE := 1.6         ## m (XZ distance) to talk to an NPC
const PLACEHOLDER_PX := Vector2i(96, 216)   ## generated placeholder image size (same 4:9 frame as the art)

extends Node3D
## 2.5D presentation of the slice. Shows LoopState/Story through their signals and queries,
## and feeds back only the thin interface: Story.player_x (from Hari), Story.nearby_target.
## Swapping this scene for another presentation leaves the logic and tests untouched.

const Spec = preload("res://logic/hari_spec.gd")
const StoryData = preload("res://logic/story_data.gd")
const HariBody = preload("res://scenes/hari.gd")
const CameraRig = preload("res://scenes/camera_rig.gd")
const Surface = preload("res://scenes/textured_surface.gd")
const Billboard = preload("res://scenes/billboard_art.gd")
const ScreenCards = preload("res://ui/screen_cards.gd")
const NotesToast = preload("res://ui/notes_toast.gd")
const Whiteout = preload("res://ui/whiteout.gd")

const HARI_START := Vector3(7.5, 0, 1.0)
const ADVAY_AT_CAR := Vector3(6.5, 0, -0.5)        # beside Manikandan, not in front of him (seen overlapping in shot p05)
const ADVAY_ON_DECK := Vector3(17.0, 0, -0.6)        # far side of the deck, not through Hari (playtest 2 screenshot)
const ADVAY_LEAVES_CAR_AFTER := 12.0       ## game minutes after 1:40
const KEYS_MOVE_SECONDS := 0.6
const CRASH_FLASH_SECONDS := 1.4
const CRASH_WHITE_SECONDS := 1.2
# Clock colour stops: [minutes, sky top, sky horizon, ambient, light colour, light energy].
const SKY_KEYS := [
	[1200.0, Color("1d1b4f"), Color("4a3f86"), Color("1c1a3a"), Color("8fa0ff"), 0.16],
	[1290.0, Color("0b0a2a"), Color("1d2055"), Color("100f26"), Color("7f8fe0"), 0.08],
	[1680.0, Color("0b0a2a"), Color("1d2055"), Color("100f26"), Color("7f8fe0"), 0.08],
	[1740.0, Color("23235e"), Color("6b4a7d"), Color("3a3058"), Color("b090c0"), 0.3],
	[1775.0, Color("4a4682"), Color("c98a86"), Color("4c4458"), Color("f0b8a0"), 0.32],
	[1795.0, Color("e98f9a"), Color("ffc477"), Color("a07068"), Color("ffc890"), 0.8],
]
const SUNRISE := [Color("ffb38a"), Color("ffe6a8"), Color("c09080"), Color("fff0d0"), 1.4]

@onready var env: Environment = $WorldEnvironment.environment
@onready var sky_light: DirectionalLight3D = $SkyLight
@onready var hari: HariBody = $Hari
@onready var rig: CameraRig = $CameraRig
@onready var manikandan: Node3D = $Manikandan
@onready var advay: Node3D = $Advay
@onready var krishna: Node3D = $Krishna
@onready var keys_icon: Node3D = $KeysIcon
@onready var suv: Node3D = $SUV
@onready var headlights: SpotLight3D = $SUV/Headlights
@onready var manikandan_sprite: Billboard = $Manikandan/Sprite
@onready var beach: Surface = $Backdrops/BeachBackdrop
@onready var fire_glow: Surface = $Backdrops/FireGlow
@onready var fire_light: OmniLight3D = $Backdrops/FireLight
@onready var toast: NotesToast = $HUD/NotesToast
@onready var cards: ScreenCards = $HUD/ScreenCards
@onready var whiteout: Whiteout = $HUD/Whiteout

var sunrise := 0.0
var _keys_path: Array[String] = []
var _keys_from := Vector3.ZERO
var _keys_t := 0.0
var _lit_key := Vector2(-1, -1)

func _ready() -> void:
	hari.camera = rig.camera
	# Nodes moved per frame in _process are not physics-interpolated (only Hari's body is).
	for n in [rig, rig.camera, advay, keys_icon, manikandan, krishna]:
		n.physics_interpolation_mode = Node.PHYSICS_INTERPOLATION_MODE_OFF
	for npc in [manikandan, advay, krishna]:
		npc.add_child(preload("res://scenes/blob_shadow.gd").new())
	add_child(preload("res://scenes/environment_fill.gd").new())       # plinth, sand, compound wall (no void past the deck)
	LoopState.loop_started.connect(_on_loop_started)
	LoopState.phone_buzz.connect(cards.show_phone)                       # visual twin: incoming-call card
	LoopState.clue_saved.connect(_on_clue_saved)
	LoopState.keys_exchanged.connect(_on_keys_exchanged)
	LoopState.advay_arrived.connect(_on_advay_arrived)
	LoopState.dawn_crash.connect(_on_dawn_crash)
	LoopState.safe_dawn.connect(_on_safe_dawn)
	LoopState.slice_ended.connect(cards.show_end_card.bind(true))
	LoopState.pause_changed.connect(cards.set_paused)
	Story.dialogue_closed.connect(_on_dialogue_closed)
	LoopState.begin_slice()

func _process(delta: float) -> void:
	Story.nearby_target = _nearest_interactable()
	_update_npcs(delta)
	_update_keys_icon(delta)
	_update_lighting()

func _nearest_interactable() -> String:
	var best := ""
	var best_d := Spec.INTERACT_RANGE
	for npc in [manikandan, krishna]:
		var d := Vector2(npc.global_position.x - hari.global_position.x, npc.global_position.z - hari.global_position.z).length()
		if npc.visible and d <= best_d:
			best_d = d
			best = npc.name.to_lower()
	return best

# --- LoopState signals -------------------------------------------------------------

func _on_loop_started(_index: int) -> void:
	cards.clear()
	whiteout.clear_white(0.8)
	sunrise = 0.0
	headlights.light_energy = 0.0
	hari.position = HARI_START
	hari.velocity = Vector3.ZERO
	hari.reset_physics_interpolation()               # teleport: don't interpolate from the old spot
	advay.position = ADVAY_AT_CAR
	_keys_path.clear()
	rig.snap()

func _on_dialogue_closed(id: String) -> void:
	if id.begins_with("amma"):
		cards.hide_phone()

func _on_clue_saved(id: String) -> void:
	toast.push(StoryData.clue(id))                                       # visual twin: notes card

func _on_keys_exchanged(from: String, to: String) -> void:
	_keys_from = _anchor(from)                                           # visual twin: keys travel
	_keys_path.assign(["hari", to] if to == "manikandan" else [to])
	_keys_t = 0.0

func _on_advay_arrived(took_keys: bool) -> void:
	advay.position = ADVAY_AT_CAR
	cards.show_caption("advay_takes_keys" if took_keys else "advay_refused")

func _on_dawn_crash() -> void:
	# visual twins: headlight sweep from the SUV, camera shake, then the white-out
	rig.shake = CRASH_FLASH_SECONDS
	whiteout.play_crash(CRASH_FLASH_SECONDS, CRASH_WHITE_SECONDS)
	var tween := create_tween()
	tween.tween_property(headlights, "light_energy", 14.0, 0.3)
	tween.parallel().tween_property(headlights, "rotation_degrees:y", -60.0, CRASH_FLASH_SECONDS).from(-120.0)

func _on_safe_dawn() -> void:
	create_tween().tween_property(self, "sunrise", 1.0, 2.5)            # visual twin: sunrise

# --- presentation ------------------------------------------------------------------

func _update_npcs(delta: float) -> void:
	var on_phone: bool = LoopState.manikandan_on_phone()
	manikandan_sprite.set_art("res://assets/art/npc/manikandan_phone.png" if on_phone else "res://assets/art/npc/manikandan.png", "phone" if on_phone else "")
	advay.visible = LoopState.advay_present()
	if advay.visible:
		var leave: bool = LoopState.clock_minutes >= LoopState.ADVAY_TIME + ADVAY_LEAVES_CAR_AFTER
		advay.position = advay.position.move_toward(ADVAY_ON_DECK if leave else ADVAY_AT_CAR, 1.4 * delta)

func _update_keys_icon(delta: float) -> void:
	if _keys_path.is_empty():
		keys_icon.position = _anchor(LoopState.keys_holder)
		return
	_keys_t += delta / KEYS_MOVE_SECONDS
	var target := _anchor(_keys_path[0])
	var t := smoothstep(0.0, 1.0, minf(_keys_t, 1.0))
	keys_icon.position = _keys_from.lerp(target, t) + Vector3(0, sin(t * PI) * 0.4, 0)
	if _keys_t >= 1.0:
		_keys_from = target
		_keys_path.pop_front()
		_keys_t = 0.0

func _anchor(holder: String) -> Vector3:
	match holder:
		"manikandan": return manikandan.position + Vector3(0.25, 1.0, 0.1)
		"advay": return advay.position + Vector3(0.3, 1.0, 0.1)
		"hari": return hari.position + Vector3(0.35, 1.0, 0.1)
		_: return suv.position + Vector3(0.6, 1.3, 1.0)                 # on the SUV's dashboard

func _update_lighting() -> void:
	var m: float = LoopState.clock_minutes
	var key := Vector2(snappedf(m, 0.5), snappedf(sunrise, 0.02))
	if key == _lit_key:
		_tint_characters(m)
		return                                  # sky material is costly to update; only on change
	_lit_key = key
	var c: Array = SKY_KEYS[0].duplicate()
	for i in range(1, SKY_KEYS.size()):
		var a: Array = SKY_KEYS[i - 1]
		var b: Array = SKY_KEYS[i]
		if m >= a[0]:
			var t := clampf((m - a[0]) / (b[0] - a[0]), 0.0, 1.0)
			for k in range(1, 5):
				c[k] = a[k].lerp(b[k], t)
			c[5] = lerpf(a[5], b[5], t)
	for k in range(1, 5):
		c[k] = c[k].lerp(SUNRISE[k - 1], sunrise)
	c[5] = lerpf(c[5], SUNRISE[4], sunrise)
	var sky_mat := env.sky.sky_material as ProceduralSkyMaterial
	sky_mat.sky_top_color = c[1]
	sky_mat.sky_horizon_color = c[2]
	sky_mat.ground_horizon_color = Color("0c0b16")            # below the horizon reads as dark land, never a flat colour field
	sky_mat.ground_bottom_color = Color("07070d")
	env.ambient_light_color = c[3]
	env.fog_light_color = c[2].darkened(0.3)
	sky_light.light_color = c[4]
	sky_light.light_energy = c[5]
	beach.set_tint(Color(0.45, 0.5, 0.75).lerp(Color.WHITE, clampf((m - 1720.0) / 75.0, 0.0, 1.0)).lerp(Color.WHITE, sunrise))
	# Fire on the village side rises from 4:45 AM, every loop.
	var glow := clampf((m - LoopState.FIRE_GLOW_TIME) / 20.0, 0.0, 1.0)
	fire_glow.set_tint(Color(1, 1, 1, glow))
	fire_light.light_energy = glow * 4.0
	_tint_characters(m)

## Characters are unshaded billboards (the cel colours stay true), so the scene's light is applied as a tint:
## cool and dim at night, warm under the deck's string lights, warm-neutral at dawn. Playtest 2: they glowed.
func _tint_characters(m: float) -> void:
	var night := Color(0.74, 0.75, 0.88)
	var dawn := Color(1.0, 0.93, 0.88)
	var t_dawn := clampf((m - 1740.0) / 60.0, 0.0, 1.0)
	for pair in [[hari, hari.get_node("Sprite")], [manikandan, manikandan_sprite], [advay, advay.get_node("Sprite")], [krishna, krishna.get_node("Sprite")]]:
		var x: float = pair[0].global_position.x
